parameters.jsCode:
const date = $('Webhook').first().json.body.preferredDate; // "2025-10-20"
const time = $('Webhook').first().json.body.preferredTime // "2:00 PM"
const [timePart, meridiem] = time.split(' ');
let [hour,min] = timePart.split(':').map(Number);
if (meridiem === 'PM' && hour !== 12) hour += 12;
if (meridiem === 'AM' && hour === 12) hour = 0;

const dtStart = new Date(date + 'T' + String(hour).padStart(2,'0') + ':' + String(min||0).padStart(2,'0') + ':00');
const dtEnd = new Date(dtStart.getTime() + 60*60*1000); // 1 hour

return [{ json: { dtStart: dtStart.toISOString(), dtEnd: dtEnd.toISOString() } }];

